import{_ as l,C as c,o as a,c as h,a0 as r,b as o,w as t,a as n,E as s,a1 as d}from"./chunks/framework.CzVS_xMp.js";const p="/ai-data-center-systems/assets/storage-network-map.CywqJgHN.svg",u="/ai-data-center-systems/assets/storage-fabric-designs.1lwi-fuW.svg",m="/ai-data-center-systems/assets/nvmeof-transport-comparison.BCbCvCzL.svg",f="/ai-data-center-systems/assets/parallel-fs-gds-infiniband.B4KIyisc.svg",v=JSON.parse('{"title":"Chapter 9: Storage Network Design and Technologies for AI Data Centers","description":"","frontmatter":{},"headers":[],"relativePath":"network/chap09/index.md","filePath":"network/chap09/index.md","lastUpdated":1788490169000}'),g={name:"network/chap09/index.md"};function b(C,e,y,P,A,w){const i=c("Mermaid");return a(),h("div",null,[e[3]||(e[3]=r('<h1 id="chapter-9-storage-network-design-and-technologies-for-ai-data-centers" tabindex="-1">Chapter 9: Storage Network Design and Technologies for AI Data Centers <a class="header-anchor" href="#chapter-9-storage-network-design-and-technologies-for-ai-data-centers" aria-label="Permalink to &quot;Chapter 9: Storage Network Design and Technologies for AI Data Centers&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#goal">Goal</a></li><li><a href="#why-storage-matters-in-aiml-fabrics">Why Storage Matters in AI/ML Fabrics</a><ul><li><a href="#training-lifecycle-and-storage-requirements">Training Lifecycle and Storage Requirements</a></li><li><a href="#local-pcie-storage-and-network-storage">Local PCIe Storage and Network Storage</a></li><li><a href="#training-network-and-storage-network">Training Network and Storage Network</a></li></ul></li><li><a href="#storage-network-design-types">Storage Network Design Types</a><ul><li><a href="#physical-fabric-ab">Physical Fabric A/B</a></li><li><a href="#logical-fabric-ab">Logical Fabric A/B</a></li><li><a href="#collapsed-fabric-ab">Collapsed Fabric A/B</a></li><li><a href="#hybrid-cloud-redundancy-and-replication">Hybrid Cloud Redundancy and Replication</a></li></ul></li><li><a href="#block-file-object-storage">Block, File, Object Storage</a></li><li><a href="#nvme-of-for-block-level-access">NVMe-oF for Block-Level Access</a><ul><li><a href="#nvme-o-tcp">NVMe-o-TCP</a></li><li><a href="#nvme-o-rdma-and-rocev2">NVMe-o-RDMA and RoCEv2</a></li><li><a href="#nvme-o-fc-and-infiniband">NVMe-o-FC and InfiniBand</a></li><li><a href="#nvme-o-tcp-and-nvme-o-rdma-comparison">NVMe-o-TCP and NVMe-o-RDMA Comparison</a></li></ul></li><li><a href="#high-performance-parallel-file-system">High-Performance Parallel File System</a><ul><li><a href="#posix-semantics">POSIX Semantics</a></li><li><a href="#hot-data-and-cold-data">Hot Data and Cold Data</a></li><li><a href="#wekafs-vast-lustre-gpfs-beegfs">WekaFS, VAST, Lustre, GPFS, BeeGFS</a></li></ul></li><li><a href="#gpudirect-storage">GPUDirect Storage</a></li><li><a href="#infiniband-for-storage">InfiniBand for Storage</a><ul><li><a href="#lid-bth-qpair">LID, BTH, QPair</a></li><li><a href="#virtual-lane-and-credit-based-flow-control">Virtual Lane and Credit-Based Flow Control</a></li><li><a href="#infiniband-and-rocev2-comparison">InfiniBand and RoCEv2 Comparison</a></li></ul></li><li><a href="#storage-network-option-comparison">Storage Network Option Comparison</a></li><li><a href="#operational-validation-checklist">Operational Validation Checklist</a></li><li><a href="#chapter-summary">Chapter Summary</a></li><li><a href="#key-terms">Key Terms</a></li><li><a href="#qa">Q&amp;A</a></li><li><a href="#references">References</a></li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>This chapter explains why storage networking is a separate design topic in AI data centers.</p><p>The core idea is:</p><blockquote><p>An AI storage network is not just a path for saving data. It is a performance path that affects GPU utilization and Job Completion Time across data preparation, training reads, checkpoint writes, model storage, inference/RAG, backup, and replication.</p></blockquote><p>The chapter focuses on these topics:</p><ul><li>Where storage fits in the AI training lifecycle</li><li>Differences between local PCIe SSD and network-attached storage</li><li>Separation between the training network and the storage network</li><li>Physical Fabric A/B, Logical Fabric A/B, collapsed fabric, and hybrid cloud replication</li><li>Differences between block, file, and object storage</li><li>NVMe over Fabrics, NVMe-o-TCP, NVMe-o-RDMA/RoCEv2, and NVMe-o-FC</li><li>NVMe-o-TCP state machine, capsules, PDUs, namespaces, and SGL/PRP</li><li>NVMe-o-RDMA over RoCEv2 session establishment and data packet format</li><li>Parallel file systems such as Lustre, GPFS, BeeGFS, WekaFS, and VAST</li><li>GPUDirect Storage, CUDA/cuFile, and GPU memory pinning</li><li>InfiniBand storage, LID, virtual lanes, and credit-based flow control</li></ul><p><img src="'+p+'" alt="AI data center storage network map"></p><h2 id="why-storage-matters-in-ai-ml-fabrics" tabindex="-1">Why Storage Matters in AI/ML Fabrics <a class="header-anchor" href="#why-storage-matters-in-ai-ml-fabrics" aria-label="Permalink to &quot;Why Storage Matters in AI/ML Fabrics&quot;">​</a></h2><p>The bottleneck in an AI data center is not determined only by GPU compute. Even if the GPUs are fast, cluster efficiency drops when data arrives late or checkpoint writes pause training.</p><p>Storage directly affects GPU utilization in these paths:</p><ul><li>Training data ingestion</li><li>Data cleanup and curation</li><li>Batch reads during training</li><li>Checkpoint writes</li><li>Model artifact storage</li><li>Fresh data access for inference services</li><li>Document retrieval for RAG and agentic RAG</li><li>Snapshots, backups, and inter-site replication</li></ul><p>Checkpointing is both a training safety mechanism and a pause source. If checkpoint writes are slow, GPUs cannot move to the next step and become idle. When this repeats, step time, p99 iteration latency, Job Completion Time, and hardware utilization all degrade.</p><h3 id="training-lifecycle-and-storage-requirements" tabindex="-1">Training Lifecycle and Storage Requirements <a class="header-anchor" href="#training-lifecycle-and-storage-requirements" aria-label="Permalink to &quot;Training Lifecycle and Storage Requirements&quot;">​</a></h3><p>Each phase of the AI lifecycle needs different storage behavior.</p><table tabindex="0"><thead><tr><th>Phase</th><th>Main Operation</th><th>Storage Requirement</th></tr></thead><tbody><tr><td>Data ingestion</td><td>Collect internal or external source data</td><td>Large capacity, stable sequential read/write</td></tr><tr><td>Processing and curation</td><td>Cleanup, transformation, deduplication</td><td>Metadata handling, random read/write, pipeline parallelism</td></tr><tr><td>Training</td><td>GPU batch reads</td><td>High aggregate read bandwidth, low tail latency</td></tr><tr><td>Checkpoint</td><td>Save model state</td><td>Fast sustained write, minimal pause</td></tr><tr><td>Model storage</td><td>Store artifacts, versions, and weights</td><td>Durability, version management, replication</td></tr><tr><td>Inference/RAG</td><td>Access fresh files, documents, and embeddings</td><td>Random read, object/file APIs, geographic proximity</td></tr><tr><td>Backup/archive</td><td>Store cold data</td><td>Cost efficiency, cloud/object tier, long-term retention</td></tr></tbody></table><p>From an operations perspective, &quot;Is the storage fast enough?&quot; is too vague. Better questions are:</p><ul><li>Are batch reads blocking the dataloader?</li><li>Does GPU idle time increase during checkpoint writes?</li><li>Are hot data and cold data mixed in the same system?</li><li>Is the metadata server or namespace the bottleneck?</li><li>Is the bottleneck the storage NIC, PCIe bus, CPU, or system memory?</li><li>How does the tuning responsibility change when the storage transport is TCP versus RDMA?</li></ul><h3 id="local-pcie-storage-and-network-storage" tabindex="-1">Local PCIe Storage and Network Storage <a class="header-anchor" href="#local-pcie-storage-and-network-storage" aria-label="Permalink to &quot;Local PCIe Storage and Network Storage&quot;">​</a></h3><p>Local PCIe SSD is storage directly attached to the server&#39;s internal PCIe bus. It has very low latency and is simple, but it has weak sharing and scaling properties for large training clusters.</p><p>Network-connected storage reaches remote SSD/HDD arrays or storage clusters through a dedicated storage NIC or HBA. It adds network hops and protocol overhead compared with local PCIe, but it enables capacity scaling, redundancy, shared access, and centralized operations.</p><table tabindex="0"><thead><tr><th>Item</th><th>Local PCIe SSD</th><th>Network Storage</th></tr></thead><tbody><tr><td>Location</td><td>Inside the GPU server</td><td>Remote storage array or storage node</td></tr><tr><td>Strength</td><td>Very low latency, simple failure scope</td><td>Capacity expansion, shared access, replication, centralized operations</td></tr><tr><td>Weakness</td><td>Server-local capacity limit, hard to share</td><td>Fabric, NIC, and protocol tuning required</td></tr><tr><td>AI fit</td><td>Cache, scratch, small jobs</td><td>Large datasets, checkpoints, shared namespace</td></tr></tbody></table><p>The source chapter explains that even though server-internal buses such as PCIe Gen5 and Gen6 provide very high bandwidth, large AI clusters still need remote storage attached through a network. Large LLM training cannot usually satisfy dataset and checkpoint requirements with only per-server local SSDs.</p><h3 id="training-network-and-storage-network" tabindex="-1">Training Network and Storage Network <a class="header-anchor" href="#training-network-and-storage-network" aria-label="Permalink to &quot;Training Network and Storage Network&quot;">​</a></h3><p>AI servers usually participate in multiple network paths.</p><table tabindex="0"><thead><tr><th>Network</th><th>Main Traffic</th><th>Common Requirement</th></tr></thead><tbody><tr><td>Training network</td><td>GPU-to-GPU, AllReduce, model weight exchange</td><td>Ultra-low latency, RoCEv2/InfiniBand, congestion control</td></tr><tr><td>Storage network</td><td>Dataset reads, checkpoint writes, model storage</td><td>High read/write throughput, path redundancy, storage protocol tuning</td></tr><tr><td>Frontend network</td><td>User/API, control, management</td><td>EVPN-VXLAN, tenant/service routing</td></tr></tbody></table><p>Storage NICs commonly need at least 100G or 200G links. High-performance environments may also use 400G or 800G. Bandwidth is not the only issue. Checkpoint write patterns, dataloader read patterns, metadata load, file-system semantics, and storage transport all affect training efficiency.</p><h2 id="storage-network-design-types" tabindex="-1">Storage Network Design Types <a class="header-anchor" href="#storage-network-design-types" aria-label="Permalink to &quot;Storage Network Design Types&quot;">​</a></h2><p>The common requirement for storage network design is stability. Performance matters, but an unstable storage path can cause training job restarts, checkpoint corruption, and data pipeline delays.</p><p>The source chapter describes several redundancy designs.</p><p><img src="'+u+'" alt="Storage fabric redundancy design options"></p><h3 id="physical-fabric-a-b" tabindex="-1">Physical Fabric A/B <a class="header-anchor" href="#physical-fabric-a-b" aria-label="Permalink to &quot;Physical Fabric A/B&quot;">​</a></h3><p>Physical Fabric A/B connects storage NIC A and storage NIC B to separate physical fabrics. Storage arrays are also separated into A and B sides.</p><p>Benefits:</p><ul><li>Failure domains are clear.</li><li>Fabric B can provide the same capacity when Fabric A fails.</li><li>The model fits enterprise storage operations.</li><li>Capacity planning is straightforward.</li></ul><p>Trade-offs:</p><ul><li>Cost is high.</li><li>Hardware and cabling are close to doubled.</li><li>Capacity symmetry between the two fabrics must be maintained.</li></ul><p>This design fits environments where the backup path must provide the same IOPS, bandwidth, and latency as the production path. The goal is not just a live failover link; it is failover that preserves training performance.</p><h3 id="logical-fabric-a-b" tabindex="-1">Logical Fabric A/B <a class="header-anchor" href="#logical-fabric-a-b" aria-label="Permalink to &quot;Logical Fabric A/B&quot;">​</a></h3><p>Logical Fabric A/B separates A and B logical paths over one physical fabric using mechanisms such as path attributes, overlays, multipath drivers, EVPN-VXLAN, and MAC-VRFs.</p><p>Examples:</p><ul><li>Storage NIC driver multipath</li><li>IP fabric path attributes</li><li>EVPN-VXLAN overlay</li><li>Route Target-based EVPN instance separation</li><li>MAC-VRF or IP-VRF-based tenant and storage-domain separation</li></ul><p>The advantage is cost and flexibility. Logical separation can be built without fully duplicating physical equipment. The downside is that the failure domain is not fully independent at the physical layer. If policy and telemetry are wrong, A and B paths may still share the same real bottleneck.</p><h3 id="collapsed-fabric-a-b" tabindex="-1">Collapsed Fabric A/B <a class="header-anchor" href="#collapsed-fabric-a-b" aria-label="Permalink to &quot;Collapsed Fabric A/B&quot;">​</a></h3><p>Collapsed Fabric is suitable for small inference edges, small remote sites, or distributed storage use cases. Servers and storage targets attach to the same switch pair or small fabric.</p><p>Benefits:</p><ul><li>Fewer devices are needed.</li><li>Deployment and operations are simpler.</li><li>It fits geographically distributed inference sites.</li></ul><p>Warnings:</p><ul><li>Redundancy and capacity are limited.</li><li>If long-distance replication is required, deep-buffer switches or TCP-based transport may be a better fit.</li><li>Maintaining lossless RDMA over distances such as 40 km or more is difficult.</li></ul><h3 id="hybrid-cloud-redundancy-and-replication" tabindex="-1">Hybrid Cloud Redundancy and Replication <a class="header-anchor" href="#hybrid-cloud-redundancy-and-replication" aria-label="Permalink to &quot;Hybrid Cloud Redundancy and Replication&quot;">​</a></h3><p>A hybrid design uses on-prem storage and cloud/object storage together. Hot data and checkpoints stay in local high-performance storage during training, while snapshots, archives, and cold data are sent to cloud object storage.</p><p>Common properties:</p><ul><li>On-prem high-performance file system or NVMe storage</li><li>Cloud S3 or object storage tier</li><li>Firewall cluster or DC gateway path</li><li>IPsec or HTTPS security tunnel</li><li>Possible redundant backup through more than one cloud provider</li></ul><p>For inference and RAG, fresh data may need to be close to users. In that case, the combination of cloud/object storage with local cache or a distributed file system becomes important.</p><h2 id="block-file-object-storage" tabindex="-1">Block, File, Object Storage <a class="header-anchor" href="#block-file-object-storage" aria-label="Permalink to &quot;Block, File, Object Storage&quot;">​</a></h2><p>AI data centers can use block, file, and object storage. This distinction is not tied 1:1 to the network transport. For example, block storage can run over Ethernet/IP, Fibre Channel, or InfiniBand. File storage can also use Ethernet/IP or RDMA transport.</p><table tabindex="0"><thead><tr><th>Type</th><th>Access Model</th><th>Representative Technology</th><th>AI Data Center Use</th></tr></thead><tbody><tr><td>Block storage</td><td>Fixed-size block, volume</td><td>NVMe-oF, SAN, NVMe-o-TCP, NVMe-o-RDMA</td><td>Low-latency volume, checkpoint, hot block storage</td></tr><tr><td>File storage</td><td>File and directory namespace</td><td>NFS, pNFS, Lustre, GPFS, BeeGFS, WekaFS, VAST</td><td>Shared dataset, POSIX workload, training/inference</td></tr><tr><td>Object storage</td><td>Object plus metadata API</td><td>S3-compatible storage, cloud object storage</td><td>Archive, backup, RAG corpus, cold data</td></tr></tbody></table><p>Block storage is strong for high-performance I/O and low latency. However, it is different from the model that uses an OS page cache or POSIX file semantics.</p><p>File storage fits ML frameworks well because PyTorch and TensorFlow commonly use Linux file APIs and POSIX semantics such as <code>open()</code>, <code>read()</code>, <code>write()</code>, <code>stat()</code>, and <code>unlink()</code>.</p><p>Object storage is strong for cost-effective scale and cloud integration. It is usually not used directly in the training hot path because of latency and API behavior. It is commonly paired with tiering, cache, data movers, or a unified namespace.</p><h2 id="nvme-of-for-block-level-access" tabindex="-1">NVMe-oF for Block-Level Access <a class="header-anchor" href="#nvme-of-for-block-level-access" aria-label="Permalink to &quot;NVMe-oF for Block-Level Access&quot;">​</a></h2><p>NVMe over Fabrics, NVMe-oF, extends the NVMe queue model and command semantics over a network fabric.</p><p>Key points:</p><ul><li>NVMe base semantics are preserved.</li><li>Only the transport changes: TCP, RDMA/RoCEv2, InfiniBand, Fibre Channel, and so on.</li><li>The host places commands in a Submission Queue, SQ.</li><li>The controller target returns completions through a Completion Queue, CQ.</li><li>NVMe-oF uses command capsules and response capsules.</li><li>Namespace, NSID, is the logical block unit that the target presents to the host.</li><li>PRP or SGL describes the host memory buffer location.</li></ul><p><img src="'+m+'" alt="NVMe-oF transport comparison"></p><h3 id="nvme-o-tcp" tabindex="-1">NVMe-o-TCP <a class="header-anchor" href="#nvme-o-tcp" aria-label="Permalink to &quot;NVMe-o-TCP&quot;">​</a></h3><p>NVMe-o-TCP carries NVMe-oF over TCP/IP. It commonly uses TCP destination port <code>8009</code>.</p><p>Benefits:</p><ul><li>It runs on ordinary Ethernet/IP fabrics.</li><li>A lossless fabric is not required.</li><li>NIC requirements are lower, and it is cost competitive.</li><li>It fits existing IP routing, BGP, IGP, firewall, and telemetry models.</li><li>It can use multi-core CPUs and the TCP stack to produce high IOPS.</li></ul><p>Trade-offs:</p><ul><li>CPU involvement is higher than with RDMA.</li><li>Latency may be higher than NVMe-o-RDMA or InfiniBand.</li><li>Host CPU, TCP stack, socket API, and queue-depth tuning matter.</li></ul><p>NVMe-o-TCP session establishment follows this basic flow:</p>',74)),(a(),o(d,null,{default:t(()=>[s(i,{id:"mermaid-946",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0AsequenceDiagram%0A%20%20%20%20participant%20H%20as%20Host%20%2F%20Initiator%0A%20%20%20%20participant%20T%20as%20Controller%20%2F%20Target%0A%0A%20%20%20%20H-%3E%3ET%3A%20TCP%20SYN%20to%20port%208009%0A%20%20%20%20T--%3E%3EH%3A%20TCP%20SYN-ACK%0A%20%20%20%20H-%3E%3ET%3A%20TCP%20ACK%0A%20%20%20%20H-%3E%3ET%3A%20NVMe%2FTCP%20IC%20Req%20PDU%0A%20%20%20%20T--%3E%3EH%3A%20IC%20Req%20Response%20PDU%0A%20%20%20%20H-%3E%3ET%3A%20NVMe%20Connect%20Request%0A%20%20%20%20T--%3E%3EH%3A%20NVMe%20Connect%20Response%0A%20%20%20%20H-%3E%3ET%3A%20Capsule%20Command%20PDU%0A%20%20%20%20T--%3E%3EH%3A%20Data%20PDU%20%2F%20Capsule%20Response%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<p>In a read operation, the host places read opcode <code>0x02</code>, NSID, command ID, data length, and SGL/PRP information into the command capsule. The target sends controller-to-host data, C2HData PDUs, and then returns a completion response.</p><p>In a write operation, in-capsule writes and off-capsule writes are possible. An in-capsule write carries data inside the command capsule payload. An off-capsule write can be better for larger data transfers and out-of-order write operations.</p><h3 id="nvme-o-rdma-and-rocev2" tabindex="-1">NVMe-o-RDMA and RoCEv2 <a class="header-anchor" href="#nvme-o-rdma-and-rocev2" aria-label="Permalink to &quot;NVMe-o-RDMA and RoCEv2&quot;">​</a></h3><p>NVMe-o-RDMA uses RDMA transport instead of TCP. In Ethernet environments, RoCEv2 is the common option.</p><p>The flow is:</p><ol><li>NVMe-oF discovery uses TCP <code>8009</code>.</li><li>RDMA Connection Management uses UDP <code>4420</code> with RoCEv2.</li><li>The QP enters Ready to Send, RTS, state.</li><li>NVMe RDMA Connect Capsules are exchanged.</li><li>NVMe I/O Queues are created.</li><li>Actual RoCEv2 data transfer carries NVMe capsules and data over UDP <code>4791</code>.</li></ol>',6)),(a(),o(d,null,{default:t(()=>[s(i,{id:"mermaid-994",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0AsequenceDiagram%0A%20%20%20%20participant%20H%20as%20Host%20%2F%20Initiator%0A%20%20%20%20participant%20T%20as%20Controller%20%2F%20Target%0A%0A%20%20%20%20H-%3E%3ET%3A%20NVMe-oF%20Discovery%2C%20TCP%208009%0A%20%20%20%20T--%3E%3EH%3A%20Discovery%20Log%20Page%20%2F%20transport%20capability%0A%20%20%20%20H-%3E%3ET%3A%20RDMA%20CM%20Request%2C%20UDP%204420%0A%20%20%20%20T--%3E%3EH%3A%20RDMA%20CM%20Reply%0A%20%20%20%20H-%3E%3ET%3A%20RDMA%20CM%20Ready%2C%20QP%20Ready%0A%20%20%20%20H-%3E%3ET%3A%20NVMe%20RDMA%20Connect%20Capsule%0A%20%20%20%20T--%3E%3EH%3A%20NVMe%20Connect%20Response%0A%20%20%20%20H-%3E%3ET%3A%20NVMe%20I%2FO%20Queue%20Create%0A%20%20%20%20T--%3E%3EH%3A%20NVMe%20Queue%20Response%0A%20%20%20%20H-%3E%3ET%3A%20RoCEv2%20data%20transfer%2C%20UDP%204791%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=r(`<p>Benefits of NVMe-o-RDMA/RoCEv2:</p><ul><li>CPU load is lower because of NIC/RDMA offload.</li><li>Ramp-up and write latency can be better.</li><li>It fits hot data, low-latency block access, and GPUDirect Storage.</li></ul><p>Warnings:</p><ul><li>It is UDP-based, so it has no native TCP flow control.</li><li>Reliable RDMA behavior depends on the NIC/RDMA state machine and the lossless fabric.</li><li>PFC, ECN, DCQCN, queue depth, and buffer utilization tuning are required.</li><li>Do not assume the storage RoCEv2 fabric should use the same DCQCN values as the training RoCEv2 fabric.</li></ul><p>An NVMe-o-RDMA over RoCEv2 packet conceptually has this structure:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ethernet</span></span>
<span class="line"><span>IP</span></span>
<span class="line"><span>UDP dst 4791</span></span>
<span class="line"><span>RoCEv2 BTH</span></span>
<span class="line"><span>IB / RDMA layer</span></span>
<span class="line"><span>NVMe command: QID, NSID, Command ID, SGL</span></span>
<span class="line"><span>Data</span></span></code></pre></div><p>RoCEv2 BTH carries QPair information, while the NVMe command carries namespace and memory descriptor information. The NVMe I/O SQ/CQ pair maps 1:1 to an RDMA QPair. The chapter notes that multiplexing multiple I/O SQ/CQ pairs onto one QPair is not supported for NVMe-o-RDMA over RoCEv2.</p><h3 id="nvme-o-fc-and-infiniband" tabindex="-1">NVMe-o-FC and InfiniBand <a class="header-anchor" href="#nvme-o-fc-and-infiniband" aria-label="Permalink to &quot;NVMe-o-FC and InfiniBand&quot;">​</a></h3><p>NVMe-o-FC can use existing Fibre Channel SANs. It is attractive in brownfield enterprise storage environments. It can use FC lossless behavior, zoning, and mature SAN operations, but cost and scaling flexibility may be limited in greenfield AI data centers.</p><p>InfiniBand can also be used as an NVMe-o-RDMA transport. Native InfiniBand provides low latency, credit-based flow control, lightweight encapsulation, and Subnet Manager-based address allocation. Compared with Ethernet/IP, it can be more limited in vendor ecosystem, network virtualization, multi-tenancy, and troubleshooting flexibility.</p><h3 id="nvme-o-tcp-and-nvme-o-rdma-comparison" tabindex="-1">NVMe-o-TCP and NVMe-o-RDMA Comparison <a class="header-anchor" href="#nvme-o-tcp-and-nvme-o-rdma-comparison" aria-label="Permalink to &quot;NVMe-o-TCP and NVMe-o-RDMA Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>NVMe-o-TCP</th><th>NVMe-o-RDMA / RoCEv2</th></tr></thead><tbody><tr><td>Transport</td><td>TCP/IP</td><td>UDP/IP + RoCEv2/RDMA</td></tr><tr><td>Fabric requirement</td><td>Lossy IP is possible</td><td>Lossless or near-lossless tuning required</td></tr><tr><td>CPU load</td><td>Relatively higher</td><td>Lower through NIC/RDMA offload</td></tr><tr><td>Latency</td><td>Medium</td><td>Low</td></tr><tr><td>Operational difficulty</td><td>Lower</td><td>Higher</td></tr><tr><td>Main tuning</td><td>TCP, MTU, CPU cores, queue/thread</td><td>PFC, ECN, DCQCN, queue depth, buffer</td></tr><tr><td>Best fit</td><td>Cold/warm storage, general IP storage</td><td>Hot block storage, low latency, GDS</td></tr></tbody></table><p>The practical decision is not simply &quot;RDMA is faster.&quot; RDMA is fast, but it requires lossless fabric and NIC tuning. TCP uses more CPU, but it scales more easily on ordinary IP fabrics.</p><h2 id="high-performance-parallel-file-system" tabindex="-1">High-Performance Parallel File System <a class="header-anchor" href="#high-performance-parallel-file-system" aria-label="Permalink to &quot;High-Performance Parallel File System&quot;">​</a></h2><p>For AI training, a 1:1 block session between one host and one controller is often not enough. Many GPU servers need to see the same dataset path while reading, writing, and sharing metadata at the same time.</p><p>This is where parallel file systems matter.</p><p>Representative examples:</p><ul><li>Lustre</li><li>IBM GPFS / Spectrum Scale</li><li>BeeGFS</li><li>WekaFS</li><li>VAST</li></ul><p><img src="`+f+'" alt="Parallel file systems, GPUDirect Storage, and InfiniBand storage"></p><h3 id="posix-semantics" tabindex="-1">POSIX Semantics <a class="header-anchor" href="#posix-semantics" aria-label="Permalink to &quot;POSIX Semantics&quot;">​</a></h3><p>ML frameworks such as PyTorch and TensorFlow commonly use POSIX file APIs.</p><p>Examples:</p><ul><li><code>open()</code></li><li><code>read()</code></li><li><code>write()</code></li><li><code>mkdir()</code></li><li><code>unlink()</code></li><li><code>stat()</code></li></ul><p>PyTorch can create serialized files such as <code>.pt</code>, <code>.npy</code>, <code>.ckpt</code>, <code>.h5</code>, and <code>.bin</code>. From the framework&#39;s view, this is a normal file write. Behind the file interface, the storage system can map it to parallel chunks, metadata, RDMA transport, local NVMe, or a cloud S3 tier.</p><p>Benefits of parallel file systems:</p><ul><li>Many clients access the same namespace.</li><li>Data and metadata are distributed across storage nodes.</li><li>Aggregate bandwidth and IOPS increase.</li><li>Training datasets and checkpoints can use the same namespace.</li><li>It is easier to connect an on-prem hot tier with a cloud cold tier.</li></ul><h3 id="hot-data-and-cold-data" tabindex="-1">Hot Data and Cold Data <a class="header-anchor" href="#hot-data-and-cold-data" aria-label="Permalink to &quot;Hot Data and Cold Data&quot;">​</a></h3><p>AI storage should separate hot data and cold data.</p><table tabindex="0"><thead><tr><th>Type</th><th>Location</th><th>Examples</th></tr></thead><tbody><tr><td>Hot data</td><td>On-prem NVMe/flash, backend storage fabric</td><td>Active dataset, training checkpoint, scratch</td></tr><tr><td>Cold data</td><td>Cloud object storage, S3, archive tier</td><td>Old checkpoint, raw archive, backup, RAG corpus</td></tr></tbody></table><p>Hot data needs latency, throughput, and metadata speed. Cold data needs cost efficiency, durability, replication, and access control.</p><p>Systems such as WekaFS can combine Tier 1 local RDMA storage with Tier 2 S3 object storage. The application uses POSIX file APIs, and the storage system handles hot/cold placement and tiering.</p><h3 id="wekafs-vast-lustre-gpfs-beegfs" tabindex="-1">WekaFS, VAST, Lustre, GPFS, BeeGFS <a class="header-anchor" href="#wekafs-vast-lustre-gpfs-beegfs" aria-label="Permalink to &quot;WekaFS, VAST, Lustre, GPFS, BeeGFS&quot;">​</a></h3><p>The source chapter uses WekaFS as an example, where a storage client can reach local storage nodes through RoCEv2 or InfiniBand transport and then move cold data to a cloud S3 tier.</p><p>From an operations perspective, PoC testing should separate these workloads:</p><table tabindex="0"><thead><tr><th>Test</th><th>Meaning</th></tr></thead><tbody><tr><td>Sequential read</td><td>Dataloader reads large shards sequentially</td></tr><tr><td>Random read</td><td>Small files and metadata-heavy access</td></tr><tr><td>Multi-file random read</td><td>Many workers access shards or files at the same time</td></tr><tr><td>Sequential write</td><td>Checkpoint write</td></tr><tr><td>Random write</td><td>Metadata, shard update, mixed workload</td></tr><tr><td>Small file metadata test</td><td>Namespace and metadata-server bottleneck</td></tr></tbody></table><p>The actual impact on the training job matters more than a simple benchmark number. Storage benchmarks may look good while GPU utilization still drops because of dataloader workers, CPU, PCIe, NIC queues, or metadata locks.</p><h2 id="gpudirect-storage" tabindex="-1">GPUDirect Storage <a class="header-anchor" href="#gpudirect-storage" aria-label="Permalink to &quot;GPUDirect Storage&quot;">​</a></h2><p>GPUDirect Storage, GDS, is an NVIDIA technology that reduces CPU and system-memory copies in the data movement path between GPU memory and storage devices.</p><p>Conventional path:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Storage -&gt; NIC -&gt; system memory -&gt; CPU involvement -&gt; GPU memory</span></span></code></pre></div><p>GDS path:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Storage -&gt; RDMA/NIC -&gt; GPU memory</span></span></code></pre></div><p>GDS reduces:</p><ul><li>CPU load</li><li>System memory bandwidth pressure</li><li>PCIe bus contention</li><li>Intermediate copies</li><li>Jitter</li><li>Competing connection overhead</li></ul><p>GDS integrates with CUDA APIs. An application or library can allocate and pin GPU memory buffers through flows such as <code>cudaMalloc()</code> and <code>cuFileBufRegister()</code>. Memory pinning fixes the physical address mapping used by DMA/RDMA.</p><p>Important practical points:</p><ul><li>GDS is better understood as a data path between storage and GPU memory, not just a storage product name.</li><li>It fits RoCEv2 or InfiniBand RDMA transport.</li><li>Each parallel file system vendor may integrate with GDS differently.</li><li>The effect may be limited in small clusters, but CPU and memory cost reduction can matter significantly in clusters with 100,000 GPUs or more.</li></ul><h2 id="infiniband-for-storage" tabindex="-1">InfiniBand for Storage <a class="header-anchor" href="#infiniband-for-storage" aria-label="Permalink to &quot;InfiniBand for Storage&quot;">​</a></h2><p>InfiniBand is a low-latency transport long used in HPC and AI clusters. It can also be used for storage as an NVMe-o-RDMA transport or as part of a GPUDirect Storage path.</p><p>Properties:</p><ul><li>Lightweight encapsulation</li><li>Requires InfiniBand switches and HCAs/NICs</li><li>Subnet Manager assigns LIDs</li><li>Link-level credit-based flow control</li><li>Virtual lane-based QoS</li><li>Uses BTH and QPair concepts, like RoCEv2</li></ul><h3 id="lid-bth-qpair" tabindex="-1">LID, BTH, QPair <a class="header-anchor" href="#lid-bth-qpair" aria-label="Permalink to &quot;LID, BTH, QPair&quot;">​</a></h3><p>InfiniBand addressing uses LID, Local Identifier.</p><table tabindex="0"><thead><tr><th>Field</th><th>Role</th></tr></thead><tbody><tr><td>LRH</td><td>Local Routing Header, includes S-LID/D-LID</td></tr><tr><td>GRH</td><td>Global Routing Header, used for routing between subnets</td></tr><tr><td>BTH</td><td>Base Transport Header, opcode and destination QPair</td></tr><tr><td>ETH</td><td>Extended Transport Header</td></tr><tr><td>Payload</td><td>NVMe capsule or RDMA data</td></tr><tr><td>ICRC/VCRC</td><td>Integrity checks</td></tr></tbody></table><p>The Subnet Manager assigns a 16-bit LID to endpoints. Switches forward based on the destination LID. GRH may be absent inside the same subnet.</p><p>In a storage context, NVMe command capsules, response capsules, and SGL information can be carried in the InfiniBand payload. QPair values connect to NVMe SQEs and CQEs.</p><h3 id="virtual-lane-and-credit-based-flow-control" tabindex="-1">Virtual Lane and Credit-Based Flow Control <a class="header-anchor" href="#virtual-lane-and-credit-based-flow-control" aria-label="Permalink to &quot;Virtual Lane and Credit-Based Flow Control&quot;">​</a></h3><p>InfiniBand QoS uses Virtual Lanes, VLs. A physical link can carry several logical lanes, and each lane can have independent queueing and flow-control behavior.</p><p>Credit-Based Flow Control, CBFC, works like this:</p><ol><li>The receiver or next-hop switch tells the sender how much buffer credit is available.</li><li>The sender transmits on that VL only when sufficient credit exists.</li><li>If there is no credit, the sender keeps the packet in its buffer.</li><li>A credit usually represents capacity at a segment or 64-byte granularity.</li></ol><p>CBFC has a similar goal to Ethernet PFC, but the mechanism differs.</p><table tabindex="0"><thead><tr><th>Item</th><th>InfiniBand CBFC</th><th>Ethernet PFC</th></tr></thead><tbody><tr><td>Mechanism</td><td>Credit-based</td><td>Pause-frame-based</td></tr><tr><td>Unit</td><td>Segment, per-VL</td><td>Priority class</td></tr><tr><td>Sender behavior</td><td>Does not transmit without credit</td><td>Stops class transmission after pause</td></tr><tr><td>Strength</td><td>Native lossless behavior</td><td>Fits Ethernet/IP ecosystem</td></tr><tr><td>Risk</td><td>Latency increase when credit is exhausted</td><td>HOL blocking, PFC storm</td></tr></tbody></table><h3 id="infiniband-and-rocev2-comparison" tabindex="-1">InfiniBand and RoCEv2 Comparison <a class="header-anchor" href="#infiniband-and-rocev2-comparison" aria-label="Permalink to &quot;InfiniBand and RoCEv2 Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>InfiniBand</th><th>Ethernet/RoCEv2</th></tr></thead><tbody><tr><td>Transport</td><td>Native IB</td><td>Ethernet/IP/UDP + IB BTH</td></tr><tr><td>Addressing</td><td>LID, Subnet Manager</td><td>MAC/IP, routing protocol</td></tr><tr><td>Flow control</td><td>CBFC, VL</td><td>PFC, ECN, DCQCN</td></tr><tr><td>Multi-tenancy</td><td>Limited</td><td>Rich options such as EVPN-VXLAN and VRF</td></tr><tr><td>Vendor ecosystem</td><td>Limited</td><td>Broad</td></tr><tr><td>Operational visibility</td><td>Can feel like a black box</td><td>Can use IP/Ethernet telemetry</td></tr><tr><td>Strength</td><td>Ultra-low latency, HPC friendly</td><td>Scale, cost, vendor diversity, programmability</td></tr></tbody></table><p>The source chapter explains that InfiniBand remains important as a high-performance storage and training transport, but Ethernet/RoCEv2 is also a strong option for large-scale AI data centers because of cost, scale, and operational flexibility.</p><h2 id="storage-network-option-comparison" tabindex="-1">Storage Network Option Comparison <a class="header-anchor" href="#storage-network-option-comparison" aria-label="Permalink to &quot;Storage Network Option Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Inference</th><th>Training</th><th>Ultra-low latency</th><th>File access</th><th>Block access</th><th>Ethernet/IP</th><th>Lossless required</th><th>Operational flexibility</th></tr></thead><tbody><tr><td>pNFS / parallel file system</td><td>Good</td><td>Good</td><td>Medium</td><td>Yes</td><td>No</td><td>Yes</td><td>Usually no</td><td>High</td></tr><tr><td>NVMe-o-TCP</td><td>Good</td><td>Limited</td><td>Medium</td><td>No</td><td>Yes</td><td>Yes</td><td>No</td><td>High</td></tr><tr><td>NVMe-o-RDMA / RoCEv2</td><td>Good</td><td>Good</td><td>High</td><td>No</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Medium</td></tr><tr><td>InfiniBand</td><td>Limited</td><td>Good</td><td>High</td><td>Some systems</td><td>Yes</td><td>No</td><td>Native lossless</td><td>Low</td></tr><tr><td>Object / S3</td><td>Good</td><td>Poor fit for hot path</td><td>Low</td><td>API-based</td><td>No</td><td>Yes</td><td>No</td><td>High</td></tr></tbody></table><p>Selection depends on workload phase and I/O pattern.</p><table tabindex="0"><thead><tr><th>Condition</th><th>First Option to Evaluate</th></tr></thead><tbody><tr><td>Many GPUs read the same dataset path</td><td>Parallel file system</td></tr><tr><td>Checkpoint writes create training pauses</td><td>Fast file system, NVMe-oF, GDS</td></tr><tr><td>Ordinary IP fabric and cost efficiency matter</td><td>NVMe-o-TCP</td></tr><tr><td>CPU load and latency are critical</td><td>NVMe-o-RDMA/RoCEv2 or InfiniBand</td></tr><tr><td>Cloud archive and RAG corpus</td><td>Object storage / S3</td></tr><tr><td>Brownfield FC SAN exists</td><td>NVMe-o-FC</td></tr><tr><td>NVIDIA GPU memory direct path is required</td><td>GPUDirect Storage</td></tr></tbody></table><h2 id="operational-validation-checklist" tabindex="-1">Operational Validation Checklist <a class="header-anchor" href="#operational-validation-checklist" aria-label="Permalink to &quot;Operational Validation Checklist&quot;">​</a></h2><p>Storage networks must be validated with both synthetic benchmarks and real training workloads.</p><p>Checklist:</p><ul><li>Confirm the training network and storage network are intentionally separated.</li><li>Confirm storage NIC speed, PCIe generation, and PCIe lane width.</li><li>Measure checkpoint write time together with GPU idle time.</li><li>Change dataloader worker counts to find read bottlenecks.</li><li>Measure sequential read/write and random read/write separately.</li><li>Run a separate small-file metadata workload.</li><li>Check p99 and p999 storage latency.</li><li>Verify whether bandwidth and latency are preserved during storage fabric A/B failover.</li><li>Confirm logical A/B separation does not share the same real physical bottleneck.</li><li>For NVMe-o-TCP, check CPU cores, TCP retransmissions, MTU, queue depth, and threads.</li><li>For NVMe-o-RDMA/RoCEv2, check PFC, ECN, DCQCN, queue depth, and buffer occupancy.</li><li>Validate the RDMA storage fabric DCQCN profile separately from the training fabric.</li><li>When using GDS, confirm CPU and system-memory copies actually decrease.</li><li>For parallel file systems, validate data/metadata distribution and node-failure behavior.</li><li>For hybrid cloud tiers, validate bandwidth, consistency, security tunnels, and restore time.</li><li>Record job-level metrics: GPU utilization, p99 step time, checkpoint pause, and Job Completion Time.</li></ul>',73)),(a(),o(d,null,{default:t(()=>[s(i,{id:"mermaid-2142",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20model%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20test%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20signal%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20M%5BStorage%20model%3Cbr%2F%3Eblock%2C%20file%2C%20object%5D%3A%3A%3Amodel%0A%20%20%20%20F%5BFabric%20design%3Cbr%2F%3EA%2FB%2C%20logical%2C%20hybrid%5D%3A%3A%3Amodel%0A%20%20%20%20W%5BRun%20workload%3Cbr%2F%3Edataloader%2C%20checkpoint%2C%20RAG%5D%3A%3A%3Atest%0A%20%20%20%20S%5BMeasure%20signals%3Cbr%2F%3EIOPS%2C%20latency%2C%20queues%2C%20CPU%2C%20GPU%20idle%5D%3A%3A%3Asignal%0A%20%20%20%20D%7BGPU%20job%20target%3Cbr%2F%3Emet%20without%20stalls%3F%7D%3A%3A%3Aaccent%0A%20%20%20%20A%5BAccept%20envelope%5D%3A%3A%3Amodel%0A%20%20%20%20R%5BRetune%20protocol%2C%3Cbr%2F%3Efabric%2C%20cache%2C%20tier%2C%20or%20file%20system%5D%3A%3A%3Aaccent%0A%0A%20%20%20%20M%20--%3E%20F%20--%3E%20W%20--%3E%20S%20--%3E%20D%0A%20%20%20%20D%20--%3E%7CYes%7C%20A%0A%20%20%20%20D%20--%3E%7CNo%7C%20R%0A%20%20%20%20R%20-.-%3E%20W%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[n(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=r('<h2 id="chapter-summary" tabindex="-1">Chapter Summary <a class="header-anchor" href="#chapter-summary" aria-label="Permalink to &quot;Chapter Summary&quot;">​</a></h2><p>The main takeaways:</p><ul><li>AI data center storage is directly connected to training performance.</li><li>Slow checkpoint writes increase GPU idle time and Job Completion Time.</li><li>Local PCIe SSD is fast, but it is limited as large-scale shared training storage.</li><li>Network storage provides scale, sharing, and redundancy, but fabric and protocol tuning are required.</li><li>The storage network is often designed separately from the training network.</li><li>Physical Fabric A/B provides strong separation but costs more.</li><li>Logical Fabric A/B improves cost and flexibility, but real path diversity must be verified.</li><li>Hybrid cloud replication connects on-prem hot data with cloud cold data.</li><li>Block storage fits low-latency volume access such as NVMe-oF.</li><li>File storage fits AI frameworks because of POSIX semantics and shared namespaces.</li><li>Object storage fits archive, backup, RAG, and cloud tiers.</li><li>NVMe-o-TCP scales easily on ordinary IP fabrics, but it uses CPU and the TCP stack.</li><li>NVMe-o-RDMA/RoCEv2 provides low latency and CPU offload, but requires lossless tuning.</li><li>Parallel file systems solve concurrent file access and metadata scaling across many GPU nodes.</li><li>GPUDirect Storage reduces copies between storage and GPU memory.</li><li>InfiniBand provides native low latency and credit-based flow control, but operational flexibility may be lower than Ethernet.</li></ul><h2 id="key-terms" tabindex="-1">Key Terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Storage network</td><td>Dedicated network or fabric used to access storage outside the server</td></tr><tr><td>Local PCIe SSD</td><td>Local SSD attached to the server&#39;s internal PCIe bus</td></tr><tr><td>Checkpoint</td><td>Recovery point that stores model state during training</td></tr><tr><td>JCT</td><td>Job Completion Time</td></tr><tr><td>Block storage</td><td>Storage organized as fixed-size blocks or volumes</td></tr><tr><td>File storage</td><td>Storage based on file and directory namespaces</td></tr><tr><td>Object storage</td><td>Storage based on objects and metadata/API access</td></tr><tr><td>NVMe-oF</td><td>NVMe over Fabrics</td></tr><tr><td>NVMe-o-TCP</td><td>NVMe-oF carried over TCP/IP</td></tr><tr><td>NVMe-o-RDMA</td><td>NVMe-oF carried over RDMA transport</td></tr><tr><td>NVMe-o-FC</td><td>NVMe-oF carried over Fibre Channel</td></tr><tr><td>Capsule</td><td>Protocol object that carries NVMe-oF commands or responses</td></tr><tr><td>PDU</td><td>Protocol Data Unit</td></tr><tr><td>NSID</td><td>Namespace Identifier</td></tr><tr><td>SGL</td><td>Scatter Gather List</td></tr><tr><td>PRP</td><td>Physical Region Page</td></tr><tr><td>SQ</td><td>Submission Queue</td></tr><tr><td>CQ</td><td>Completion Queue</td></tr><tr><td>QPair</td><td>RDMA Queue Pair</td></tr><tr><td>POSIX</td><td>Standard Unix/Linux file API and behavior model</td></tr><tr><td>GDS</td><td>GPUDirect Storage</td></tr><tr><td>cuFile</td><td>NVIDIA GDS user library interface</td></tr><tr><td>LID</td><td>InfiniBand Local Identifier</td></tr><tr><td>VL</td><td>InfiniBand Virtual Lane</td></tr><tr><td>CBFC</td><td>Credit-Based Flow Control</td></tr></tbody></table><h2 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A&quot;">​</a></h2><h3 id="_1-why-is-the-storage-network-important-in-an-ai-data-center" tabindex="-1">1. Why is the storage network important in an AI data center? <a class="header-anchor" href="#_1-why-is-the-storage-network-important-in-an-ai-data-center" aria-label="Permalink to &quot;1. Why is the storage network important in an AI data center?&quot;">​</a></h3><p>Storage determines how long GPUs wait for data. If dataloader reads are slow or checkpoint writes take too long, GPUs become idle and step time and Job Completion Time increase. Storage is therefore not a secondary infrastructure component; it is a data path that determines GPU cluster efficiency.</p><h3 id="_2-what-is-the-difference-between-local-pcie-ssd-and-network-storage" tabindex="-1">2. What is the difference between local PCIe SSD and network storage? <a class="header-anchor" href="#_2-what-is-the-difference-between-local-pcie-ssd-and-network-storage" aria-label="Permalink to &quot;2. What is the difference between local PCIe SSD and network storage?&quot;">​</a></h3><p>Local PCIe SSD has very low latency and is simple, but it is isolated per server. Network storage has fabric and protocol overhead, but it provides shared capacity, redundancy, scale-out, and centralized operations. Large training environments often need network storage.</p><h3 id="_3-why-do-checkpoint-writes-matter" tabindex="-1">3. Why do checkpoint writes matter? <a class="header-anchor" href="#_3-why-do-checkpoint-writes-matter" aria-label="Permalink to &quot;3. Why do checkpoint writes matter?&quot;">​</a></h3><p>Checkpoints are required for failure recovery, but slow writes pause training. Checkpoint pauses increase GPU idle time, p99 step time, and JCT. The checkpoint path must therefore be validated for sustained write bandwidth and tail latency.</p><h3 id="_4-what-is-the-difference-between-physical-fabric-a-b-and-logical-fabric-a-b" tabindex="-1">4. What is the difference between Physical Fabric A/B and Logical Fabric A/B? <a class="header-anchor" href="#_4-what-is-the-difference-between-physical-fabric-a-b-and-logical-fabric-a-b" aria-label="Permalink to &quot;4. What is the difference between Physical Fabric A/B and Logical Fabric A/B?&quot;">​</a></h3><p>Physical Fabric A/B separates equipment and links physically. Failure domains are clear and failover capacity is easier to guarantee, but the design costs more. Logical Fabric A/B separates paths over the same physical fabric using policy, overlays, or multipath drivers. It costs less, but the real bottleneck sharing must be verified.</p><h3 id="_5-when-is-nvme-o-tcp-a-good-fit" tabindex="-1">5. When is NVMe-o-TCP a good fit? <a class="header-anchor" href="#_5-when-is-nvme-o-tcp-a-good-fit" aria-label="Permalink to &quot;5. When is NVMe-o-TCP a good fit?&quot;">​</a></h3><p>NVMe-o-TCP is a good fit when you want to use an ordinary Ethernet/IP fabric and build cost-effective storage without lossless tuning. It fits cold/warm storage, inference storage, and general block access. CPU and TCP stack load and latency still need to be considered.</p><h3 id="_6-when-is-nvme-o-rdma-rocev2-a-good-fit" tabindex="-1">6. When is NVMe-o-RDMA/RoCEv2 a good fit? <a class="header-anchor" href="#_6-when-is-nvme-o-rdma-rocev2-a-good-fit" aria-label="Permalink to &quot;6. When is NVMe-o-RDMA/RoCEv2 a good fit?&quot;">​</a></h3><p>It is a good fit when low latency, fast ramp-up, CPU offload, and hot block storage are important. However, it requires PFC, ECN, DCQCN, queue depth, and buffer tuning. The storage RoCEv2 profile should be validated separately from the training fabric profile.</p><h3 id="_7-why-do-parallel-file-systems-appear-often-in-ai-training" tabindex="-1">7. Why do parallel file systems appear often in AI training? <a class="header-anchor" href="#_7-why-do-parallel-file-systems-appear-often-in-ai-training" aria-label="Permalink to &quot;7. Why do parallel file systems appear often in AI training?&quot;">​</a></h3><p>Many GPU servers need to read and write the same file namespace at the same time. Systems such as Lustre, GPFS, BeeGFS, WekaFS, and VAST distribute data and metadata to increase aggregate bandwidth and IOPS while providing POSIX semantics.</p><h3 id="_8-what-does-gpudirect-storage-reduce" tabindex="-1">8. What does GPUDirect Storage reduce? <a class="header-anchor" href="#_8-what-does-gpudirect-storage-reduce" aria-label="Permalink to &quot;8. What does GPUDirect Storage reduce?&quot;">​</a></h3><p>It reduces CPU and system-memory copies in the data path between GPU memory and storage devices. This can reduce CPU load, PCIe/system-memory pressure, jitter, and intermediate copy overhead.</p><h3 id="_9-how-are-infiniband-cbfc-and-ethernet-pfc-different" tabindex="-1">9. How are InfiniBand CBFC and Ethernet PFC different? <a class="header-anchor" href="#_9-how-are-infiniband-cbfc-and-ethernet-pfc-different" aria-label="Permalink to &quot;9. How are InfiniBand CBFC and Ethernet PFC different?&quot;">​</a></h3><p>InfiniBand CBFC is credit-based. The receiver or next-hop gives buffer credits, and the sender transmits only when credits exist. Ethernet PFC is pause-frame-based and pauses an entire priority class. CBFC is close to native lossless behavior, but latency can increase when credits are exhausted. PFC risks HOL blocking and PFC storms.</p><h3 id="_10-what-are-the-most-important-measurements-in-a-storage-network-poc" tabindex="-1">10. What are the most important measurements in a storage network PoC? <a class="header-anchor" href="#_10-what-are-the-most-important-measurements-in-a-storage-network-poc" aria-label="Permalink to &quot;10. What are the most important measurements in a storage network PoC?&quot;">​</a></h3><p>Storage IOPS and bandwidth alone are not enough. Measure GPU utilization, dataloader wait, checkpoint pause, p99/p999 storage latency, CPU load, PCIe bandwidth, NIC queues, ECN/PFC/RDMA counters, and metadata operation latency.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://blogs.oracle.com/linux/nvme-over-tcp" target="_blank" rel="noreferrer">Alan Adamson, &quot;NVMe over TCP,&quot; Oracle Linux Blog, September 9, 2020</a></li><li><a href="https://nvmexpress.org/specifications/" target="_blank" rel="noreferrer">NVM Express Specifications</a></li><li><a href="https://simplyblock.io/glossary/nvme-over-tcp-vs-nvme-over-rdma/" target="_blank" rel="noreferrer">NVMe over TCP vs NVMe over RDMA</a></li><li><a href="https://docs.nvidia.com/gpudirect-storage/design-guide/contents.html" target="_blank" rel="noreferrer">NVIDIA, &quot;GPUDirect Storage Design Guide&quot;</a></li><li><a href="https://docs.nvidia.com/cuda/archive/13.0.0/cuda-c-programming-guide/contents.html" target="_blank" rel="noreferrer">NVIDIA, &quot;CUDA C++ Programming Guide 13.0&quot;</a></li><li><a href="https://www.infinibandta.org/ibta-releases-new-infiniband-architecture-specification/" target="_blank" rel="noreferrer">InfiniBand Trade Association, &quot;IBTA Releases New InfiniBand Architecture Specification,&quot; November 14, 2012</a></li></ul>',28))])}const I=l(g,[["render",b]]);export{v as __pageData,I as default};
